ProjectALife.DialogueShards["scenes_any_3"] = {
{"fw_ld4_misc_c_0003","any",2,"reg=civilian,family,worker,rescue",{1,"Hold this",2,"What is it?",1,"A rabbit",2,"A DEAD rabbit?",1,"I wasn't going to ask you to hold a live one, dinner's on me"}},
{"fw_ld4_misc_c_0004","any",2,"reg=civilian,family,worker,rescue",{1,"How many days since a hot shower?",2,"Eleven",1,"Twelve",2,"Does it matter?",1,"When you smell like me, it matters"}},
{"fw_ld4_misc_c_0005","any",2,"reg=civilian,family,worker,rescue",{1,"I miss my cat",2,"What was her name?",1,"Mr. Biscuit",2,"Her name was Mr. Biscuit?",1,"He, his name was Mr. Biscuit, don't judge me"}},
{"fw_ld4_misc_c_0006","any",2,"reg=civilian,family,worker,rescue",{1,"Don't look at me, I haven't brushed my hair in a week",2,"I haven't brushed my teeth",1,"That's worse",2,"I know, I can taste it, believe me"}},
{"fw_ld4_misc_c_0007","any",2,"reg=civilian,family,worker,rescue",{1,"Put your hand here, feel that?",2,"Feel what?",1,"The baby, she kicked",2,"Oh my God, that's incredible",1,"That's the only good news I've had in two months"}},
{"fw_ld4_misc_c_0008","any",2,"reg=civilian,family,worker,rescue|world=building",{1,"You okay?",2,"Fine",1,"You've been staring at that wall for twenty minutes",2,"Was it twenty? Felt like two",1,"Come here, let's sit, you don't have to talk"}},
{"fw_ld4_misc_c_0009","any",2,"reg=civilian,family,worker,rescue",{1,"What's your biggest fear?",2,"Being the last one",1,"Not dying?",2,"Dying's easy, being the last one is the nightmare"}},
{"fw_ld4_misc_c_0010","any",2,"reg=civilian,family,worker,rescue",{1,"You laugh in your sleep",2,"I do not",1,"You do, you giggle",2,"What was I giggling at?",1,"You said 'the goat has the keys'",2,"...I don't know either"}},
{"fw_ld4_misc_c_0011","any",2,"reg=civilian,family,worker,rescue",{1,"Can you teach me to shoot?",2,"Sure, hold it like this",1,"It's heavy",2,"It's supposed to be, don't point it at me",1,"Whoa- sorry- where's the safety on this thing?",2,"Right there, we'll start with that"}},
{"fw_ld4_misc_c_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Do you pray for the infected?",2,"Sometimes",1,"Why?",2,"Because somewhere in there is someone's mother",1,"...I've never thought of that, and now I can't un-think it"}},
{"fw_ld4_misc_c_0013","any",2,"reg=civilian,family,worker,rescue",{1,"Hey, I'm sorry about earlier",2,"For what?",1,"For calling you useless",2,"I was useless",1,"You weren't, you were terrified, so was I"}},
{"fw_ld4_misc_c_0014","any",2,"reg=civilian,family,worker,rescue",{1,"If you could go back to any day, which one?",2,"A random Tuesday",1,"A Tuesday?",2,"Nothing happened, nothing at all, and I didn't know how good it was"}},
{"fw_ld4_misc_c_0015","any",2,"reg=civilian,family,worker,rescue",{1,"Is it wrong that I want to just sleep for a month?",2,"Not at all",1,"And wake up when it's over",2,"I'll hold your place in line"}},
{"fw_ld4_misc_c_0016","any",2,"reg=civilian,family,worker,rescue",{1,"Whatever happens, we stick together",2,"Promise?",1,"I promise",2,"Don't make promises you can't keep",1,"I'll keep this one"}},
{"fw_ld4_misc_c_0017","any",2,"reg=civilian,family,worker,rescue",{1,"You know the worst part?",2,"Which one?",1,"The little things, like not knowing what time it is",2,"It's almost noon, I think",1,"See? You think, and I believe you, and that's enough"}},
{"fw_ld4_misc_c_0018","any",2,"reg=civilian,family,worker,rescue",{1,"I haven't looked in a mirror in days",2,"Don't",1,"Why not?",2,"Because you won't recognize yourself, and then you'll cry",1,"Is it that bad?",2,"Not bad... just, um, different"}},
{"fw_ld4_misc_c_0019","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Am I going to be okay?",2,"Yes",1,"You don't know that",2,"I know that I'm going to do everything I can to make sure of it",1,"That's the nicest thing anyone's ever said to me"}},
{"fw_ld4_misc_c_0020","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Do you ever feel like you're in a dream?",2,"Every day",1,"And what do you do?",2,"I pinch myself, and it hurts, and I remember it's real"}},
{"fw_ld4_misc_c_0021","any",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"Can you tell me a story? I can't sleep",2,"Once upon a time, there was a girl who lived in a house on a hill",1,"Was she scared?",2,"Of nothing, she was the bravest girl in the county",1,"Keep going"}},
{"fw_ld4_misc_c_0022","any",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"What's that sound?",2,"Crickets",1,"Crickets? Real crickets?",2,"Real ones, they're still singing, even now",1,"That's the best sound I've heard in weeks"}},
{"fw_ld4_misc_c_0023","any",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"Wake me when it's my turn",2,"Sleep, I'll wake you",1,"You always say that",2,"And I always do, now close your eyes"}},
{"fw_ld4_misc_c_0024","any",2,"reg=civilian,family,worker,rescue|hour=6,11",{1,"Did you sleep?",2,"Like a log",1,"Liar, I heard you toss all night",2,"Like a log that tosses, okay, fine"}},
{"fw_ld4_misc_c_0025","any",2,"reg=law,swat",{1,"You ever have a partner you couldn't stand?",2,"Every partner",1,"Even me?",2,"Especially you",1,"...that's the nicest thing you've said all week"}},
{"fw_ld4_misc_c_0026","any",2,"reg=law,swat",{1,"Do they teach this at the academy?",2,"Teach what?",1,"How to be this tired",2,"They taught us to stand up straight, nothing about the rest"}},
{"fw_ld4_misc_c_0027","any",2,"reg=law,swat",{1,"My daughter's sixteen today",2,"Happy birthday to her",1,"I'm 40 miles away and I can't call, can't send a card",2,"Say it out loud, to the air, she might hear"}},
{"fw_ld4_misc_c_0028","any",2,"reg=military,elite",{1,"Sergeant, did you ever want to be something else?",2,"A pilot",1,"What happened?",2,"Bad eyes, worse math",1,"You'd have been a good one",2,"You'd have been a good co-pilot, Private"}},
{"fw_ld4_misc_c_0029","any",2,"reg=military,elite",{1,"Smell that?",2,"Coffee",1,"Real coffee?",2,"Someone found a stash, don't tell the lieutenant",1,"My lips are sealed, pass the cup"}},
{"fw_ld4_misc_c_0030","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Why do you carry that picture?",2,"It's my mom",1,"She look like you?",2,"She looks like she'd slap you for asking"}},
{"fw_ld4_misc_c_0031","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"What's the best thing you ever stole?",2,"A trombone",1,"A TROMBONE?",2,"I don't know why either, but I learned to play it, badly"}},
{"fw_ld4_misc_c_0032","any",2,"reg=outlaw,raider,gang,club,crime,prison|world=cold",{1,"You scared?",2,"Me? No",1,"Your hands are shaking",2,"It's cold",1,"It's eighty degrees",2,"...shut up"}},
{"fw_ld4_misc_c_0033","any",2,"reg=family",{1,"Why is the sky so big, Mama?",2,"So we have somewhere to put our hopes",1,"Do hopes weigh a lot?",2,"Some do, some don't, you carry yours lightly"}},
{"fw_ld4_misc_c_0034","any",2,"reg=family",{1,"Will you hold my hand while I sleep?",2,"Course I will, sweetie",1,"Even if I snore?",2,"Especially if you snore"}},
{"fw_ld4_misc_d_0001","any",2,"reg=civilian,family,worker,rescue",{1,"I keep a list",2,"Of what?",1,"Of everyone we lost, in the back of my notebook",2,"How many names?",1,"Forty-one, I add one every time",2,"Can I see it?",1,"Not yet, someday, when I can read it out loud"}},
{"fw_ld4_misc_d_0002","any",2,"reg=civilian,family,worker,rescue",{1,"Did you bring the water?",2,"I thought you did",1,"I was on cans, you were on water",2,"I was on cans too!",1,"Then who's on water?",2,"...nobody, great, nobody's on water, we're going to die of thirst because of a clerical error"}},
{"fw_ld4_misc_d_0003","any",2,"reg=civilian,family,worker,rescue",{1,"You're humming again",2,"Sorry",1,"Don't be, I like it, what is it?",2,"I don't know, something my mom sang while she cooked",1,"It's pretty",2,"I can't remember the words, only the tune"}},
{"fw_ld4_misc_d_0004","any",2,"reg=civilian,family,worker,rescue",{1,"Do you ever want to scream?",2,"Constantly",1,"Why don't you?",2,"Because it would bring them, and because I'm afraid I'd never stop",1,"Scream into a pillow",2,"We don't have pillows"}},
{"fw_ld4_misc_d_0005","any",2,"reg=civilian,family,worker,rescue",{1,"Can I trust you?",2,"With what?",1,"With my life",2,"That's a big ask for a Tuesday",1,"It's Thursday",2,"Even bigger, yes, you can"}},
{"fw_ld4_misc_d_0006","any",2,"reg=civilian,family,worker,rescue",{1,"What do you think happens after?",2,"After what?",1,"After we die",2,"Honestly? I think it's quiet, like the best nap",1,"I hope so, I really hope so"}},
{"fw_ld4_misc_d_0007","any",2,"reg=civilian,family,worker,rescue",{1,"I stole this",2,"What is it?",1,"A mug, from a house I broke into",2,"Why?",1,"Because it says 'World's Best Dad', and I thought, someone should have it",2,"...you're a strange person, and I like you"}},
{"fw_ld4_misc_d_0008","any",2,"reg=civilian,family,worker,rescue",{1,"Tell me about your kids",2,"I have two, Ben and Maddie",1,"How old?",2,"Ten and seven, Ben likes dinosaurs, Maddie likes everything pink",1,"Where are they?",2,"...I'm going to find them, that's all I can say"}},
{"fw_ld4_misc_d_0009","any",2,"reg=civilian,family,worker,rescue",{1,"My hands won't stop shaking",2,"Let me hold them",1,"Isn't it weird?",2,"Not really, everybody does it"}},
{"fw_ld4_misc_d_0010","any",2,"reg=civilian,family,worker,rescue",{1,"I used to be afraid of spiders",2,"And now?",1,"Now it's, thank God, a spider. Not a person",2,"Hell of a thing to be grateful for"}},
{"fw_ld4_misc_d_0011","any",2,"reg=civilian,family,worker,rescue",{1,"Do you think we'll remember this?",2,"Every second",1,"I'd rather forget",2,"Then don't write anything down, and maybe you'll get lucky"}},
{"fw_ld4_misc_d_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Quick, hide!",2,"What is it?",1,"Footsteps",2,"Whose?",1,"I don't know, I don't know, shhh",2,"...it's the dog"}},
{"fw_ld4_misc_d_0013","any",2,"reg=civilian,family,worker,rescue",{1,"Let's make a pact",2,"What kind?",1,"If one of us gets bitten, the other doesn't hesitate",2,"That's morbid",1,"It's love, in a weird way"}},
{"fw_ld4_misc_d_0014","any",2,"reg=civilian,family,worker,rescue",{1,"You're limping again",2,"It's nothing",1,"It's something, sit, take your shoe off",2,"It's a blister",1,"It's the size of a quarter, you stubborn mule"}},
{"fw_ld4_misc_d_0015","any",2,"reg=civilian,family,worker,rescue",{1,"I did laundry today",2,"With what?",1,"A bucket and a bar of soap and a lot of hope",2,"Do I smell better?",1,"Marginally"}},
{"fw_ld4_misc_d_0016","any",2,"reg=civilian,family,worker,rescue",{1,"What would you do with a million dollars?",2,"Buy a loaf of bread",1,"A loaf of bread?",2,"Fresh, warm, with real butter, and eat it in the middle of a field"}},
{"fw_ld4_misc_d_0017","any",2,"reg=civilian,family,worker,rescue",{1,"I remember when my youngest was getting a tooth",2,"What was that like?",1,"Drooling, chewing on everything, crying",2,"My mother always suggested a cool clean rag",1,"How would you know?",2,"Raised three. I remember teething better than their first words"}},
{"fw_ld4_misc_d_0018","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I'm useless, aren't I?",2,"No",1,"I can't shoot, can't fight, can't cook",2,"You can listen, and you can carry, and you can keep us laughing",1,"...that's something, I guess"}},
{"fw_ld4_misc_d_0019","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I miss my dad",2,"Me too",1,"Is yours alive?",2,"I don't know",1,"Mine neither, can we pretend they are?",2,"Yeah, let's pretend"}},
{"fw_ld4_misc_d_0020","any",2,"reg=law,swat",{1,"I never got to say goodbye to my captain",2,"I'm sorry",1,"He taught me everything, and I left without a word",2,"He'd understand",1,"I hope so"}},
{"fw_ld4_misc_d_0021","any",2,"reg=law,swat",{1,"You ever think we're doing it wrong?",2,"Every day",1,"And?",2,"And we keep doing it, because the alternative is worse"}},
{"fw_ld4_misc_d_0022","any",2,"reg=law,swat",{1,"You carry that notebook everywhere",2,"It's evidence",1,"Of what?",2,"That we existed, that we tried"}},
{"fw_ld4_misc_d_0023","any",2,"reg=military,elite",{1,"Sergeant, can I ask something?",2,"Make it quick",1,"Are we the good guys?",2,"...we're the ones left, Private, that has to be enough",1,"Yes, Sergeant"}},
{"fw_ld4_misc_d_0024","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Hey, you ever been in love?",2,"Once",1,"What happened?",2,"She had better taste in men",1,"Ouch",2,"Yeah, I still think about her, every time I count my teeth"}},
{"fw_ld4_misc_d_0025","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Why do you always pick the fights?",2,"Because someone has to",1,"That's a lousy reason",2,"It's the only one I've got"}},
{"fw_ld4_misc_d_0026","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"I got you something",2,"What?",1,"A bracelet, off a dead guy",2,"...that's gross, and thoughtful, and I'm keeping it"}},
{"fw_ld4_misc_d_0027","any",2,"reg=family",{1,"Mama, are you crying?",2,"No, sweetheart, I've got something in my eye",1,"Is it a sad something?",2,"A little, but it's passing"}},
{"fw_ld4_misc_d_0028","any",2,"reg=family",{1,"Papaw, what's that you're carving?",2,"A little horse",1,"For who?",2,"For you, if you promise not to lose it",1,"I promise, I promise, I won't"}},
{"fw_ld4_misc_d_0029","any",2,"reg=family",{1,"Say your prayers",2,"Do we have to?",1,"Yes, thank God for everything, even the bad stuff",2,"Even the monsters?",1,"Especially the monsters, they remind us to be grateful for the quiet"}},
{"fw_ld4_mixed_b_0001","any",2,"reg=civilian,family,worker,rescue",{1,"How's the leg?",2,"Hurts like hell, but it's not swelling",1,"Let me see",2,"It's fine, stop fussing",1,"You limp when you think I'm not looking",2,"...okay, it hurts a lot"}},
{"fw_ld4_mixed_b_0002","any",2,"reg=civilian,family,worker,rescue",{1,"Do you have any aspirin?",2,"Two left",1,"I've got a headache that could kill a horse",2,"Take one, save one",1,"You're a saint",2,"I'm a hypocrite, I'm about to take the other one"}},
{"fw_ld4_mixed_b_0003","any",2,"reg=civilian,family,worker,rescue",{1,"I found some bandages",2,"Clean?",1,"Mostly, there's a little brown on the corner",2,"Boil them first",1,"With what?",2,"...that's a good question"}},
{"fw_ld4_mixed_b_0004","any",2,"reg=civilian,family,worker,rescue",{1,"Is he going to be okay?",2,"I don't know, I'm not a doctor",1,"But you were a nurse",2,"A dental assistant, there's a difference",1,"It's a bigger difference than I'd like"}},
{"fw_ld4_mixed_b_0005","any",2,"reg=civilian,family,worker,rescue",{1,"Does it hurt when I press here?",2,"Ow, yes, yes it does",1,"Sorry, sorry",2,"You're a terrible doctor",1,"I know, hold still"}},
{"fw_ld4_mixed_b_0006","any",2,"reg=civilian,family,worker,rescue",{1,"Did you hear a cough?",2,"Where?",1,"From the back, someone's sick",2,"Oh no, oh God, who?",1,"I don't know, don't panic, just check everyone's forehead"}},
{"fw_ld4_mixed_b_0007","any",2,"reg=civilian,family,worker,rescue",{1,"I think my fever's gone down",2,"Let me feel",1,"Cool hands",2,"Cold hands, warm heart, you're fine"}},
{"fw_ld4_mixed_b_0008","any",2,"reg=civilian,family,worker,rescue",{1,"Why are you checking my arms?",2,"Because I check everyone's arms",1,"Every night?",2,"Every night, it's the only way I can sleep"}},
{"fw_ld4_mixed_b_0009","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"Heard the news?",2,"Which news?",1,"Folks say there's a safe place up north",2,"Folks say a lot of things",1,"This time they said it with a straight face",2,"I'll believe it when I see it, and when I stop being afraid of seeing it"}},
{"fw_ld4_mixed_b_0010","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"What's the rumor today?",2,"That the Army is coming back",1,"Same one as yesterday",2,"Rumors are like leftovers, they get better with age"}},
{"fw_ld4_mixed_b_0011","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"I heard dogs last night",2,"Barking?",1,"Yeah, far off, a whole pack of them",2,"Good, maybe there's someone feeding them"}},
{"fw_ld4_mixed_b_0012","any",2,"reg=civilian,family,worker,rescue|tmp=fresh|world=vehicle",{1,"Do you think the radio will ever come back?",2,"Maybe",1,"I miss the weatherman",2,"I miss the commercials",1,"The car dealership ones, with the screaming guy?",2,"Yes, God, yes, I'd listen to him all day"}},
{"fw_ld4_mixed_b_0013","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I was supposed to start college in August",2,"What were you studying?",1,"Nursing",2,"You'd have been great",1,"I still can be, I'm learning every day, it's just the textbook is horrible"}},
{"fw_ld4_mixed_b_0014","any",2,"reg=civilian,family,worker,rescue|day=10,3650",{1,"Anybody know what day it is?",2,"Does it matter?",1,"Not really, I just like knowing",2,"It's the fourteenth, I think",1,"Of July?",2,"Of something"}},
{"fw_ld4_mixed_b_0015","any",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"Watch's quiet",2,"Good, that's how I like it",1,"I counted fifty-three stars",2,"Why?",1,"Because counting is better than thinking"}},
{"fw_ld4_mixed_b_0016","any",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"Did you hear a gunshot?",2,"Far off, maybe two miles",1,"Who's shooting?",2,"Somebody who either got lucky or didn't",1,"Go back to sleep, I'll keep watch"}},
{"fw_ld4_mixed_b_0017","any",2,"reg=law,swat",{1,"Dispatch is silent",2,"Dispatch has been silent for a week",1,"I keep hoping for a crackle",2,"I keep hoping for a pay stub"}},
{"fw_ld4_mixed_b_0018","any",2,"reg=law,swat",{1,"Do we still get hazard pay?",2,"Ha, ha, ha",1,"I'm serious",2,"That's why it's funny"}},
{"fw_ld4_mixed_b_0019","any",2,"reg=law,swat",{1,"The sheriff wants a report",2,"On what?",1,"Everything, he says",2,"I'll write 'bad' and leave the rest blank"}},
{"fw_ld4_mixed_b_0020","any",2,"reg=law,swat",{1,"Did you hear back from your wife?",2,"No",1,"Keep trying",2,"I do, every hour, on the hour, it's a ritual now"}},
{"fw_ld4_mixed_b_0021","any",2,"reg=military,elite|hour=4,9",{1,"Where's the lieutenant?",2,"Reconnaissance",1,"Alone?",2,"He said he'd be back by dawn",1,"He's an idiot",2,"He's our idiot"}},
{"fw_ld4_mixed_b_0022","any",2,"reg=military,elite",{1,"First rule of the field?",2,"Don't get killed",1,"Second rule?",2,"See rule one",1,"Good, you're learning"}},
{"fw_ld4_mixed_b_0023","any",2,"reg=military,elite",{1,"You writing in a diary?",2,"A log, Sarge",1,"What's in it?",2,"Dates, temperatures, who ate what",1,"Add a line for me, 'Sergeant Hill was right again'"}},
{"fw_ld4_mixed_b_0024","any",2,"reg=military,elite",{1,"How are the men?",2,"Tired, but holding",1,"Morale?",2,"Better than yesterday, they got a hot meal",1,"Remind me to thank the cook"}},
{"fw_ld4_mixed_b_0025","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"This new guy talks too much",2,"He's nervous",1,"I hate nervous people",2,"You hate everybody",1,"Not everybody, I like you",2,"Because I don't talk"}},
{"fw_ld4_mixed_b_0026","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"What's the split?",2,"Sixty-forty",1,"Who gets sixty?",2,"Me",1,"Sounds fair",2,"I thought it would"}},
{"fw_ld4_mixed_b_0027","any",2,"reg=family|world=vehicle",{1,"Grandma, tell us about when you were young",2,"Which part?",1,"The part where you met Grandpa",2,"He had a mustache that tickled, and a truck that sputtered, and a laugh that filled the room",1,"And you fell in love right away?",2,"I fell in love when he gave me his last sandwich"}},
{"fw_ld4_mixed_b_0028","any",2,"reg=family",{1,"Don't wander off",2,"I won't",1,"But the nice man said there's bad things out there",2,"What kind of bad things?",1,"The kind that don't like little boys who wander"}},
{"fw_ld4_mixed_b_0029","any",2,"reg=family|hour=20,5",{1,"Can I stay up?",2,"Why?",1,"I want to see the stars",2,"Fine, put your coat on, and you hold my hand the whole time",1,"I will, Mama"}},
{"fw_ld4_party_a_0001","any",2,"reg=civilian,family,worker,rescue",{1,"Who's got the can opener?",2,"Not me",1,"It was in your bag",2,"It was in MY bag? Since when do you put things in my bag?!",1,"Since you started carrying the heavy one, calm down",2,"Found it, it was under the socks, you're welcome"}},
{"fw_ld4_party_a_0002","any",2,"reg=civilian,family,worker,rescue",{1,"I'm not saying you're wrong, I'm saying you could be nicer about it",2,"Nicer? We almost died because you didn't listen!",1,"I listened!",2,"You listened and then did the opposite, that's not listening, Pam",1,"...fine, fine, I should've gone left"}},
{"fw_ld4_party_a_0003","any",2,"reg=civilian,family,worker,rescue",{1,"You're quiet today",2,"Just thinking",1,"About what?",2,"About whether I'd still be alive if I'd stayed with my sister",1,"You can't think like that",2,"I can't NOT think like that, that's the problem"}},
{"fw_ld4_party_a_0004","any",2,"reg=civilian,family,worker,rescue",{1,"Why do you always sit facing the exit?",2,"Habit, I used to wait tables",1,"And now?",2,"Now I wait for things to come through it, ha"}},
{"fw_ld4_party_a_0005","any",2,"reg=civilian,family,worker,rescue",{1,"I made you something",2,"What is it?",1,"It's a bracelet, out of shoelaces, and a bottle cap",2,"Aw, it's ugly, I love it",1,"Don't tell anyone, I have a reputation"}},
{"fw_ld4_party_a_0006","any",2,"reg=civilian,family,worker,rescue",{1,"We're out of toilet paper",2,"I know",1,"What do we use?",2,"Don't ask, just don't ask",1,"...that bad, huh?"}},
{"fw_ld4_party_a_0007","any",2,"reg=civilian,family,worker,rescue",{1,"Can I tell you something embarrassing?",2,"Please",1,"I still sleep with the night-light on, the little one shaped like a turtle",2,"Where'd you even get power for that?",1,"It's battery, and it's my only vice, don't judge me"}},
{"fw_ld4_party_a_0008","any",2,"reg=civilian,family,worker,rescue",{1,"Remember when we thought two weeks would be enough?",2,"Two weeks of what? Food?",1,"Two weeks until someone came, the Army, anybody",2,"Yeah, I remember, I also remember thinking it'd be cute to say 'I told you so' to my neighbor",1,"Did you?",2,"He's dead, so no"}},
{"fw_ld4_party_a_0009","any",2,"reg=civilian,family,worker,rescue",{1,"How do you stay so calm?",2,"I'm not calm, I'm numb",1,"That's worse",2,"It's better than screaming, I tried screaming, it attracts attention"}},
{"fw_ld4_party_a_0010","any",2,"reg=civilian,family,worker,rescue",{1,"If you could have one thing, anything, what would it be?",2,"A phone that works, so I could call my mother",1,"What would you say?",2,"'I'm okay, Mama, don't worry,' even if it's a lie",1,"I'd say the same"}},
{"fw_ld4_party_a_0011","any",2,"reg=civilian,family,worker,rescue",{1,"Who snores?",2,"Not me",1,"It's definitely you",2,"It's the dog",1,"We don't have a dog",2,"...then who was that?"}},
{"fw_ld4_party_a_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Do you think they'll ever find us?",2,"Who?",1,"Anyone, the Army, Red Cross, the National Guard",2,"I think they know where we are, they're just busy",1,"Busy doing what?",2,"Not finding us, evidently"}},
{"fw_ld4_party_a_0013","any",2,"reg=civilian,family,worker,rescue",{1,"What did you want to be when you grew up?",2,"A veterinarian",1,"Why didn't you?",2,"Math, organic chemistry, and the price of school",1,"You'd have been great",2,"Thanks, I would've, I'd have saved all the dogs"}},
{"fw_ld4_party_a_0014","any",2,"reg=civilian,family,worker,rescue",{1,"Am I supposed to feel worse than this?",2,"What do you mean?",1,"My husband. My in-laws. Half the block. I say it and there's... nothing",2,"You may not feel it all at once, honey. It can catch up with you",1,"That's what I don't want. It catching up"}},
{"fw_ld4_party_a_0015","any",2,"reg=civilian,family,worker,rescue",{1,"Let's play a game",2,"What kind of game?",1,"Name three things you're grateful for",2,"Okay, hot coffee, clean socks, you",1,"...I was going to say bullets, but yours are better"}},
{"fw_ld4_party_a_0016","any",2,"reg=civilian,family,worker,rescue",{1,"My knee is killing me",2,"Sit down, let me look",1,"It's just a bruise",2,"It's the size of a grapefruit, Marcy",1,"Fine, a big bruise, I'll walk it off",2,"You'll sit, and I'll find a rag and some cold water, no argument"}},
{"fw_ld4_party_a_0017","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I can't stop shaking",2,"Me neither",1,"Is it normal?",2,"I think so, I think it means we're still human",1,"That is the strangest thing anyone's said to me all year"}},
{"fw_ld4_party_a_0018","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Do you pray?",2,"Sometimes, mostly I just beg",1,"To who?",2,"Whoever's listening, God, Jesus, my Grandma, anyone",1,"Any luck?",2,"I'm still here, aren't I?"}},
{"fw_ld4_party_a_0019","any",2,"reg=law,swat",{1,"Your turn to brief",2,"Brief on what?",1,"Everything, supplies, routes, morale",2,"Supplies thin, routes bad, morale... let's not talk about morale",1,"Understood, skip morale"}},
{"fw_ld4_party_a_0020","any",2,"reg=law,swat",{1,"You ever think about retiring?",2,"Constantly, I had a boat picked out",1,"A boat?",2,"A little fishing boat, with an outboard, and a cooler, and no radio",1,"Sounds nice",2,"It'd be, it would've been"}},
{"fw_ld4_party_a_0021","any",2,"reg=law,swat",{1,"How's your sister?",2,"Don't know, she's in Elizabethtown, phone lines are down",1,"You'll hear from her",2,"Maybe, I tell myself that every morning"}},
{"fw_ld4_party_a_0022","any",2,"reg=law,swat",{1,"I wrote my will last night",2,"You what?",1,"Just a paragraph, who gets my truck, my badge, my gun",2,"That's morbid, Frank",1,"It's practical, and it made me feel better"}},
{"fw_ld4_party_a_0023","any",2,"reg=military,elite",{1,"Permission to ask a personal question, Sergeant",2,"Granted",1,"Do you have a family?",2,"A daughter in Fayetteville, fourteen, she plays the clarinet",1,"Is she okay?",2,"I choose to believe so, dismissed"}},
{"fw_ld4_party_a_0024","any",2,"reg=military,elite",{1,"How many weeks until my enlistment ends?",2,"Forty-one",1,"Forty-one weeks and a day",2,"You counting?",1,"Every night, it's my lullaby"}},
{"fw_ld4_party_a_0025","any",2,"reg=military,elite",{1,"Heard a rumor we're pulling back",2,"Heard a rumor we're being reinforced",1,"Which one's true?",2,"Neither, the rumor mill's been out of work since the fourth"}},
{"fw_ld4_party_a_0026","any",2,"reg=military,elite",{1,"Hey, Doc, you got anything for a headache?",2,"Water, rest, and quit swearing at the sergeant",1,"That's not medicine",2,"It's the only prescription I've got"}},
{"fw_ld4_party_a_0027","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You ever think we're the bad guys?",2,"We ARE the bad guys",1,"No, I mean, in the grand scheme",2,"In the grand scheme, there's no good guys, just hungry guys",1,"...that's the smartest thing you've said all week"}},
{"fw_ld4_party_a_0028","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You owe me a drink",2,"For what?",1,"For saving your ass yesterday",2,"Fine, you can have a drink, if you find one",1,"I'll find one, I always do"}},
{"fw_ld4_party_a_0029","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"What are you gonna do with your cut?",2,"Buy a farm",1,"With what? Nobody's selling",2,"Then I'll take one, same thing"}},
{"fw_ld4_party_a_0030","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"I'm gonna miss this place",2,"You've been here six days",1,"Longest I've stayed anywhere since '88",2,"...we should send a postcard"}},
{"fw_ld4_party_a_0031","any",2,"reg=family",{1,"Honey, did you take your pills?",2,"Yes, Mama",1,"Show me the bottle",2,"Mama, I'm forty-three",1,"And I'm sixty-eight, and I'll count the pills, thank you"}},
{"fw_ld4_party_a_0032","any",2,"reg=family|hour=16,22|world=water",{1,"Tell me about Papaw's farm again",2,"Which part?",1,"The part with the creek and the cows",2,"The creek ran cold even in August, and the cows came down at dusk, slow as molasses",1,"Keep going"}},
{"fw_ld4_party_a_0033","any",2,"reg=family",{1,"Who wants to sing?",2,"Not me",1,"Come on, 'Amazing Grace', all of us",2,"Quietly",1,"Quietly, yes, quietly, like we're in church"}},
{"fw_ld4_party_a_0034","any",2,"reg=family",{1,"I'm cold",2,"Come here, share the blanket",1,"Thanks, Mama",2,"Hush now, we'll be warm soon"}},
{"fw_ld4_quick_a_0001","any",2,"reg=civilian,family,worker,rescue",{1,"You okay?",2,"Define okay",1,"Not actively dying",2,"Then yes"}},
{"fw_ld4_quick_a_0002","any",2,"reg=civilian,family,worker,rescue",{1,"Did you sleep?",2,"In bursts",1,"Me too, like a hummingbird",2,"A very sad hummingbird"}},
{"fw_ld4_quick_a_0003","any",2,"reg=civilian,family,worker,rescue",{1,"I need a hug",2,"Come here",1,"Not so hard",2,"Sorry, I forget my own strength"}},
{"fw_ld4_quick_a_0004","any",2,"reg=civilian,family,worker,rescue",{1,"What's that smell?",2,"Me",1,"Oh",2,"Yeah, I'm sorry"}},
{"fw_ld4_quick_a_0005","any",2,"reg=civilian,family,worker,rescue",{1,"Who's got my sock?",2,"Why would I have your sock?",1,"Because you have mine",2,"...fine, here, they're both disgusting"}},
